<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller;use App\Models\Booking;use App\Services\VehicleCheckoutService;use Illuminate\Http\Request;use Inertia\Inertia;
class VehicleCheckoutController extends Controller{public function index(){return Inertia::render('Admin/Checkouts/Index',['checkouts'=>\App\Models\VehicleCheckout::with(['booking','vehicle','items'])->latest()->paginate(20)]);}public function create(Booking $booking){return Inertia::render('Admin/Checkouts/Create',['booking'=>$booking->load(['vehicle','customer'])]);}public function store(Request $r,Booking $booking,VehicleCheckoutService $s){$d=$r->validate(['odometer'=>'required|integer|min:0','fuel_level'=>'required|integer|min:0|max:100','notes'=>'nullable|string','items'=>'required|array|min:1','items.*.checklist_code'=>'required','items.*.checklist_name'=>'required','items.*.condition_status'=>'required|in:GOOD,DAMAGED,MISSING','items.*.notes'=>'nullable']);$s->checkout($booking,$d,$r->user()->id);return redirect()->route('admin.bookings.show',$booking);}}
